"""bone_flesh_1.png — Костные включения рассеяны короткими осколками: нет крупных плато, рисунок хряща сдвинут по смыслу, а не трансформацией.
Carnis · 16×16 RGBA · карта пикселей, без случайности.
Путь: src/main/resources/assets/carnis/textures/block/bone_flesh_1.png
Запуск: python3 bone_flesh_1.py [путь_выходного_PNG]; требуется Pillow.
"""
import sys
from PIL import Image
ROWS = ['5646435646435646435646434839375646435646435646438A7671947E78564643564643564643564643564643564643', '564643564643947E787A645E5646435646435646435646435646438A7671483937564643564643564643564643564643', '5646435646438A7671483937564643564643564643564643564643564643564643564643564643564643564643564643', '5646435646435646435646435646435646435646433C2F2D5646435646435646435646435646435646438A7671564643', '56464356464356464356464356464356464356464356464356464365524D65524D5646435646435646438A7671483937', '56464356464365524D65524D564643947E788A767156464356464365524D564643564643564643564643564643564643', '56464356464365524D5646435646437A645E483937564643564643564643564643564643564643564643564643564643', '5646435646435646435646435646435646435646435646435646435646435646438A7671947E78564643564643564643', '5646435646435646435646435646435646435646435646435646435646435646435646437A645E483937564643564643', '564643947E788A767156464356464365524D65524D564643564643564643564643564643564643564643564643564643', '5646438A767148393756464356464365524D5646435646435646435646435646435646435646435646433C2F2D564643', '5646435646435646435646435646435646435646438A7671947E7856464356464365524D564643564643564643564643', '5646435646435646433C2F2D5646435646435646435646437A645E48393756464365524D65524D564643564643564643', '65524D65524D5646435646435646435646435646435646435646435646435646435646435646438A7671947E78564643', '56464356464356464356464356464356464356464365524D5646435646435646435646435646435646438A7671483937', '5646435646435646438A76718A7671564643564643564643564643564643564643564643564643564643564643564643']

def build():
    im = Image.new('RGBA', (16, 16))
    for y, row in enumerate(ROWS):
        assert len(row) == 16 * 6
        for x in range(16):
            h = row[x*6:x*6+6]
            im.putpixel((x,y), (int(h[0:2],16),int(h[2:4],16),int(h[4:6],16),255))
    return im

if __name__ == '__main__':
    path = sys.argv[1] if len(sys.argv)>1 else 'bone_flesh_1.png'
    build().save(path)
    print(path)
